import{_ as e,o as d,c as l,a2 as r}from"./chunks/framework.BUwdTBzS.js";const x=JSON.parse('{"title":"dev:ask — 全功能交互式菜单","description":"","frontmatter":{"title":"dev:ask — 全功能交互式菜单"},"headers":[],"relativePath":"dev-flow/references/menu.md","filePath":"dev-flow/references/menu.md","lastUpdated":null}'),n={name:"dev-flow/references/menu.md"};function a(o,t,s,i,c,g){return d(),l("div",null,[...t[0]||(t[0]=[r(`<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/menu.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="dev-ask-—-全功能交互式菜单" tabindex="-1">dev:ask — 全功能交互式菜单 <a class="header-anchor" href="#dev-ask-—-全功能交互式菜单" aria-label="Permalink to &quot;dev:ask — 全功能交互式菜单&quot;">​</a></h1><h2 id="一、路由声明" tabindex="-1">一、路由声明 <a class="header-anchor" href="#一、路由声明" aria-label="Permalink to &quot;一、路由声明&quot;">​</a></h2><ul><li><strong>加载方式</strong>：SKILL.md 触发 → <code>read_file(&quot;references/menu.md&quot;)</code></li><li><strong>不进入步骤流程</strong>：不输出步骤完成标记 JSON，不写入工作上下文，不进入 dev-flow 步骤链</li><li><strong>交互协议</strong>：每一级菜单必须遵守&quot;双重展示&quot;规则： <ol><li>先输出 Markdown 选项表格</li><li>再调用 <code>ask_followup_question</code> 弹出交互式选项</li><li>表格行数与 options 数组长度严格一致</li><li>编号一致</li></ol></li></ul><h2 id="二、状态感知-每次加载时执行-必须" tabindex="-1">二、状态感知（每次加载时执行，必须） <a class="header-anchor" href="#二、状态感知-每次加载时执行-必须" aria-label="Permalink to &quot;二、状态感知（每次加载时执行，必须）&quot;">​</a></h2><p>以下 4 项检测在加载本文件后、弹出主菜单前执行，结果用于决定菜单选项的显示/隐藏：</p><h3 id="检测清单" tabindex="-1">检测清单 <a class="header-anchor" href="#检测清单" aria-label="Permalink to &quot;检测清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>检测项</th><th>命令</th><th>用途</th></tr></thead><tbody><tr><td>S1</td><td>活跃流程存在</td><td><code>ls ~/.codebuddy/working-context/.active-flows/*.flow 2&gt;/dev/null</code></td><td>决定 B1/B4/B5 是否显示</td></tr><tr><td>S2</td><td>已完成工作上下文</td><td><code>ls ~/.codebuddy/working-context/*.md 2&gt;/dev/null</code> + grep <code>status: (completed|testing|delivered)</code></td><td>决定 B2/B3 是否显示</td></tr><tr><td>S3</td><td>在 git 仓库中</td><td><code>git rev-parse --git-dir 2&gt;/dev/null</code></td><td>部分选项的前提</td></tr><tr><td>S4</td><td>当前分支</td><td><code>git branch --show-current 2&gt;/dev/null</code></td><td>B2/B3 匹配精度</td></tr></tbody></table><h3 id="结果处理" tabindex="-1">结果处理 <a class="header-anchor" href="#结果处理" aria-label="Permalink to &quot;结果处理&quot;">​</a></h3><ul><li>无可用选项时：<strong>不显示该选项</strong>（而非灰显），菜单保持简洁</li><li>S1 命中时：一级 B 菜单标注 <code>[🔴 有活跃流程]</code></li><li>S2 命中时：一级 B 菜单标注 <code>[🟢 有已完成需求]</code></li><li>S1 和 S2 均未命中：一级 B 菜单标注 <code>[⚪ 无相关状态]</code></li></ul><h2 id="三、一级菜单" tabindex="-1">三、一级菜单 <a class="header-anchor" href="#三、一级菜单" aria-label="Permalink to &quot;三、一级菜单&quot;">​</a></h2><blockquote><p>一级菜单始终显示全部 6 个入口，状态徽标根据 §二 检测结果动态更新。</p></blockquote><h3 id="主菜单定义" tabindex="-1">主菜单定义 <a class="header-anchor" href="#主菜单定义" aria-label="Permalink to &quot;主菜单定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>名称</th><th>状态徽标</th><th>进入</th></tr></thead><tbody><tr><td style="text-align:center;">A</td><td>🚀 开始新的开发任务</td><td>—</td><td>→ §四-A</td></tr><tr><td style="text-align:center;">B</td><td>🔄 继续已有需求 / 修复问题</td><td><code>{动态}</code></td><td>→ §四-B</td></tr><tr><td style="text-align:center;">C</td><td>📝 同步文档与知识管理</td><td>—</td><td>→ §四-C</td></tr><tr><td style="text-align:center;">D</td><td>📊 查看状态、度量与可视化</td><td>—</td><td>→ §四-D</td></tr><tr><td style="text-align:center;">E</td><td>🛠 工具：项目接入、流程图、帮助</td><td>—</td><td>→ §四-E</td></tr><tr><td style="text-align:center;">F</td><td>❓ 场景向导（不确定该用什么？）</td><td>—</td><td>→ §四-F</td></tr></tbody></table><h3 id="交互指令" tabindex="-1">交互指令 <a class="header-anchor" href="#交互指令" aria-label="Permalink to &quot;交互指令&quot;">​</a></h3><p><strong>必须</strong>先输出以下表格，再立即调用 <code>ask_followup_question</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选项 A：🚀 开始新的开发任务</span></span>
<span class="line"><span>选项 B：🔄 继续已有需求 / 修复问题 {S1/S2 徽标}</span></span>
<span class="line"><span>选项 C：📝 同步文档与知识管理</span></span>
<span class="line"><span>选项 D：📊 查看状态、度量与可视化</span></span>
<span class="line"><span>选项 E：🛠 工具：项目接入、流程图、帮助</span></span>
<span class="line"><span>选项 F：❓ 场景向导（不确定该用什么？帮我判断）</span></span></code></pre></div><p><strong>ask_followup_question 参数</strong>：</p><ul><li>question: &quot;请选择你要使用的功能：&quot;</li><li>options: 6 个选项（与表格逐条对应）</li><li>multiSelect: false</li></ul><h2 id="四、二级菜单-全部展开定义" tabindex="-1">四、二级菜单（全部展开定义） <a class="header-anchor" href="#四、二级菜单-全部展开定义" aria-label="Permalink to &quot;四、二级菜单（全部展开定义）&quot;">​</a></h2><hr><h3 id="§四-a-🚀-开始新的开发任务" tabindex="-1">§四-A：🚀 开始新的开发任务 <a class="header-anchor" href="#§四-a-🚀-开始新的开发任务" aria-label="Permalink to &quot;§四-A：🚀 开始新的开发任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>名称</th><th>说明</th><th>背后命令</th><th style="text-align:center;">行为类型</th></tr></thead><tbody><tr><td style="text-align:center;">A1</td><td>📌 标准开发</td><td>常规功能开发/Bug修复（阶段0→步骤1→...）</td><td><code>dev-flow &lt;描述&gt;</code></td><td style="text-align:center;"><strong>需输入→入流程</strong></td></tr><tr><td style="text-align:center;">A2</td><td>⚡ 精简模式</td><td>减少交互确认，叠加 <code>--fast</code></td><td><code>dev-flow --fast &lt;描述&gt;</code></td><td style="text-align:center;"><strong>需输入→入流程</strong></td></tr><tr><td style="text-align:center;">A3</td><td>🔧 快速修复</td><td>≤3文件 + ≤10行/文件 + 已知位置</td><td><code>--micro &lt;位置&gt; &lt;改动&gt;</code></td><td style="text-align:center;"><strong>需输入→入流程</strong></td></tr><tr><td style="text-align:center;">A0</td><td>← 返回主菜单</td><td>回到一级菜单</td><td>—</td><td style="text-align:center;"><strong>导航</strong></td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（A0/A1/A2/A3），用户选择后：</p><ul><li>A0：重新显示一级主菜单（§三）</li><li>A1/A2：弹文本提示&quot;请描述你要开发或修复的内容：&quot;→ 收集描述 → 执行 <code>dev-flow [--fast] &lt;描述&gt;</code></li><li>A3：弹文本提示&quot;请提供文件路径、行号和改动描述（如 <code>src/utils.ts L42 修复拼写</code>）：&quot;→ 收集 → 评估阈值 → 进入 micro-fix 或提示降级</li></ul><hr><h3 id="§四-b-🔄-继续已有需求-修复问题" tabindex="-1">§四-B：🔄 继续已有需求 / 修复问题 <a class="header-anchor" href="#§四-b-🔄-继续已有需求-修复问题" aria-label="Permalink to &quot;§四-B：🔄 继续已有需求 / 修复问题&quot;">​</a></h3><p><strong>状态感知规则</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>名称</th><th>前提条件</th><th>背后命令</th><th style="text-align:center;">行为类型</th></tr></thead><tbody><tr><td style="text-align:center;">B1</td><td>▶️ 恢复上次中断的流程</td><td>S1=命中</td><td>自然语言描述相关话题</td><td style="text-align:center;"><strong>入流程</strong></td></tr><tr><td style="text-align:center;">B2</td><td>🔄 迭代修复（提测反馈等）</td><td>S2=命中</td><td><code>dev:fix --iteration &quot;描述&quot;</code></td><td style="text-align:center;"><strong>需输入→入流程</strong></td></tr><tr><td style="text-align:center;">B3</td><td>🔀 需求漂移处理</td><td>S2=命中</td><td><code>dev:fix --drift &quot;描述&quot;</code></td><td style="text-align:center;"><strong>需输入→入流程</strong></td></tr><tr><td style="text-align:center;">B4</td><td>📦 继续下一批</td><td>S1=命中 + .flow 中 batch_mode=true</td><td>&quot;继续下一批&quot;</td><td style="text-align:center;"><strong>入流程</strong></td></tr><tr><td style="text-align:center;">B5</td><td>🎚 切换交互模式</td><td>S1=命中</td><td>&quot;少问我&quot; / &quot;每步都问我&quot;</td><td style="text-align:center;"><strong>需选择→执行</strong></td></tr><tr><td style="text-align:center;">B0</td><td>← 返回主菜单</td><td>始终显示（子菜单存在时）</td><td>—</td><td style="text-align:center;"><strong>导航</strong></td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格（仅包含条件满足的选项 + B0）+ <code>ask_followup_question</code>，用户选择后：</p><ul><li>B0：重新显示一级主菜单（§三）</li><li>B1：提示&quot;请描述你想继续做什么：&quot;→ 进入活跃流程恢复</li><li>B2：提示&quot;请描述本次反馈/问题：&quot;→ 执行 <code>dev:fix --iteration &quot;描述&quot;</code></li><li>B3：提示&quot;请描述需求变更内容：&quot;→ 执行 <code>dev:fix --drift &quot;描述&quot;</code></li><li>B4：直接执行&quot;继续下一批&quot;</li><li>B5：弹选项&quot;少问我（精简模式）/ 每步都问我（标准模式）&quot;→ 直接切换</li></ul><p><strong>S1/S2 均未命中时</strong>：B 子菜单不打开（不显示 <code>ask_followup_question</code>），主菜单 B 项标注 <code>[⚪ 无相关状态]</code>，点选后直接提示&quot;当前未检测到活跃流程或已完成需求。请使用 A 开始新任务，或 F 场景向导帮你判断。&quot;</p><hr><h3 id="§四-c-📝-同步文档与知识管理" tabindex="-1">§四-C：📝 同步文档与知识管理 <a class="header-anchor" href="#§四-c-📝-同步文档与知识管理" aria-label="Permalink to &quot;§四-C：📝 同步文档与知识管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>名称</th><th>说明</th><th>背后命令</th><th style="text-align:center;">行为类型</th></tr></thead><tbody><tr><td style="text-align:center;">C1</td><td>📄 全量文档同步</td><td>devlog + knowledge + 文档平台 + 工作上下文</td><td><code>dev:sync</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">C2</td><td>🧠 知识库管理</td><td>查看/扫描/搜索/沉淀项目知识</td><td><code>dev:kb</code></td><td style="text-align:center;"><strong>入流程</strong></td></tr><tr><td style="text-align:center;">C0</td><td>← 返回主菜单</td><td>回到一级菜单</td><td>—</td><td style="text-align:center;"><strong>导航</strong></td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（C0/C1/C2），用户选择后：</p><ul><li>C0：重新显示一级主菜单（§三）</li><li>C1：直接执行 <code>dev:sync</code></li><li>C2：进入 <code>dev:kb</code> 知识库管理流程</li></ul><hr><h3 id="§四-d-📊-查看状态、度量与可视化" tabindex="-1">§四-D：📊 查看状态、度量与可视化 <a class="header-anchor" href="#§四-d-📊-查看状态、度量与可视化" aria-label="Permalink to &quot;§四-D：📊 查看状态、度量与可视化&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>名称</th><th>背后命令</th><th style="text-align:center;">行为类型</th></tr></thead><tbody><tr><td style="text-align:center;">D1</td><td>📈 流程进度概览</td><td><code>dev:status</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">D2</td><td>🔍 实时观测（Token/红牌/耗时）</td><td><code>dev:status --trace</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">D3</td><td>📊 开发度量（最近 5 次）</td><td><code>dev:metrics</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">D4</td><td>📋 全部历史度量</td><td><code>dev:metrics --all</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">D5</td><td>📈 度量趋势分析</td><td><code>dev:metrics --trend</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">D6</td><td>📑 指定需求度量报告</td><td><code>dev:metrics --report &lt;ID&gt;</code></td><td style="text-align:center;"><strong>需输入</strong></td></tr><tr><td style="text-align:center;">D7</td><td>📐 可视化仪表盘</td><td><code>dev:metrics --dashboard</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">D0</td><td>← 返回主菜单</td><td>回到一级菜单</td><td style="text-align:center;"><strong>导航</strong></td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（D0/D1/D2/.../D7），用户选择后：</p><ul><li>D0：重新显示一级主菜单（§三）</li><li>D1~D5, D7：直接执行对应命令</li><li>D6：提示&quot;请输入需求 ID（或需求关键词）：&quot;→ 收集后执行</li></ul><hr><h3 id="§四-e-🛠-工具-项目接入、流程图、帮助" tabindex="-1">§四-E：🛠 工具：项目接入、流程图、帮助 <a class="header-anchor" href="#§四-e-🛠-工具-项目接入、流程图、帮助" aria-label="Permalink to &quot;§四-E：🛠 工具：项目接入、流程图、帮助&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>名称</th><th>背后命令</th><th style="text-align:center;">行为类型</th></tr></thead><tbody><tr><td style="text-align:center;">E1</td><td>🆕 项目接入 / 刷新 profile</td><td><code>dev:onboard</code></td><td style="text-align:center;"><strong>入流程</strong></td></tr><tr><td style="text-align:center;">E2</td><td>📐 生成/更新流程图</td><td><code>dev:flowchart</code></td><td style="text-align:center;"><strong>入流程</strong></td></tr><tr><td style="text-align:center;">E3</td><td>📖 查看完整帮助</td><td><code>dev:help</code></td><td style="text-align:center;"><strong>即执行</strong></td></tr><tr><td style="text-align:center;">E0</td><td>← 返回主菜单</td><td>回到一级菜单</td><td style="text-align:center;"><strong>导航</strong></td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（E0/E1/E2/E3），用户选择后：</p><ul><li>E0：重新显示一级主菜单（§三）</li><li>E1~E3：执行对应命令</li></ul><hr><h3 id="§四-f-❓-场景向导" tabindex="-1">§四-F：❓ 场景向导 <a class="header-anchor" href="#§四-f-❓-场景向导" aria-label="Permalink to &quot;§四-F：❓ 场景向导&quot;">​</a></h3><h2 id="§四-f-❓-场景向导-决策树式多轮问答" tabindex="-1">§四-F：❓ 场景向导（决策树式多轮问答） <a class="header-anchor" href="#§四-f-❓-场景向导-决策树式多轮问答" aria-label="Permalink to &quot;§四-F：❓ 场景向导（决策树式多轮问答）&quot;">​</a></h2><blockquote><p>通过 2 轮交互式问答帮用户定位到正确的命令。</p></blockquote><h3 id="第一轮-判断场景大类" tabindex="-1">第一轮：判断场景大类 <a class="header-anchor" href="#第一轮-判断场景大类" aria-label="Permalink to &quot;第一轮：判断场景大类&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>场景描述</th><th style="text-align:center;">进入</th></tr></thead><tbody><tr><td style="text-align:center;">F1</td><td>我有一个新需求/新功能要开发</td><td style="text-align:center;">→ §F.1</td></tr><tr><td style="text-align:center;">F2</td><td>之前走完流程的需求，现在又发现新问题/新反馈需要修复</td><td style="text-align:center;">→ §F.2</td></tr><tr><td style="text-align:center;">F3</td><td>之前走完流程的需求，又改了代码，只想同步文档</td><td style="text-align:center;">→ §F.3</td></tr><tr><td style="text-align:center;">F4</td><td>产品/需求方改了需求，需要同步更新</td><td style="text-align:center;">→ §F.4</td></tr><tr><td style="text-align:center;">F5</td><td>上次开发中断了，想接着做</td><td style="text-align:center;">→ §F.5</td></tr><tr><td style="text-align:center;">F6</td><td>需要跨多个项目仓库协作修复</td><td style="text-align:center;">→ §F.6</td></tr><tr><td style="text-align:center;">F7</td><td>流程走完了，但仪表盘/度量/文档数据不对</td><td style="text-align:center;">→ §F.7</td></tr><tr><td style="text-align:center;">F0</td><td>← 返回主菜单</td><td style="text-align:center;">回到一级菜单</td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（F0/F1/F2/.../F7），用户选择后：</p><ul><li>F0：重新显示一级主菜单（§三）</li><li>F1~F7：进入对应第二轮</li></ul><h3 id="第二轮-细化并推荐" tabindex="-1">第二轮：细化并推荐 <a class="header-anchor" href="#第二轮-细化并推荐" aria-label="Permalink to &quot;第二轮：细化并推荐&quot;">​</a></h3><h4 id="§f-1-新需求开发" tabindex="-1">§F.1 新需求开发 <a class="header-anchor" href="#§f-1-新需求开发" aria-label="Permalink to &quot;§F.1 新需求开发&quot;">​</a></h4><p>进一步判断复杂度 → 推荐 A1/A2/A3。</p><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>引导问题</th><th>推荐</th></tr></thead><tbody><tr><td style="text-align:center;">F1a</td><td>改动可能涉及多文件/多模块</td><td>A1 标准开发</td></tr><tr><td style="text-align:center;">F1b</td><td>希望减少交互确认</td><td>A2 精简模式</td></tr><tr><td style="text-align:center;">F1c</td><td>只是想改个拼写/加个判空（已知位置）</td><td>A3 快速修复</td></tr><tr><td style="text-align:center;">F1d</td><td>不确定，帮我评估</td><td>A1 标准开发（默认）</td></tr><tr><td style="text-align:center;">F1e</td><td>← 返回上一级</td><td>回到 F 第一轮场景选择</td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（F1a/F1b/F1c/F1d/F1e），用户选择后：</p><ul><li>F1e：重新显示 F 第一轮场景选择（§四-F 第一轮）</li><li>F1a~F1d：进入&quot;场景向导终结规则&quot;（§四-F 终结规则），根据推荐命令提示执行</li></ul><h4 id="§f-2-完成后又发现问题-反馈" tabindex="-1">§F.2 完成后又发现问题/反馈 <a class="header-anchor" href="#§f-2-完成后又发现问题-反馈" aria-label="Permalink to &quot;§F.2 完成后又发现问题/反馈&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>引导问题</th><th>推荐命令</th></tr></thead><tbody><tr><td style="text-align:center;">F2a</td><td>改动较大（&gt;3 文件 或 &gt;30 行），需要完整跟踪记录</td><td><code>dev:fix --iteration &quot;描述&quot;</code></td></tr><tr><td style="text-align:center;">F2b</td><td>改动较小，仅需同步文档</td><td><code>dev:sync</code></td></tr><tr><td style="text-align:center;">F2c</td><td>不确定改动范围</td><td>先 <code>dev:status</code> 查看上下文，再决定</td></tr><tr><td style="text-align:center;">F2d</td><td>← 返回上一级</td><td>回到 F 第一轮场景选择</td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（F2a/F2b/F2c/F2d），用户选择后：</p><ul><li>F2d：重新显示 F 第一轮场景选择（§四-F 第一轮）</li><li>F2a~F2c：进入&quot;场景向导终结规则&quot;（§四-F 终结规则），根据推荐命令提示执行</li></ul><h4 id="§f-3-完成后改了代码-只想同步文档" tabindex="-1">§F.3 完成后改了代码，只想同步文档 <a class="header-anchor" href="#§f-3-完成后改了代码-只想同步文档" aria-label="Permalink to &quot;§F.3 完成后改了代码，只想同步文档&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>引导问题</th><th>推荐命令</th></tr></thead><tbody><tr><td style="text-align:center;">F3a</td><td>改动量小，只需把最新状态同步到文档</td><td><code>dev:sync</code></td></tr><tr><td style="text-align:center;">F3b</td><td>改动有一定规模，想生成 commit 并完整同步</td><td><code>dev:fix --iteration &quot;描述&quot;</code></td></tr><tr><td style="text-align:center;">F3c</td><td>← 返回上一级</td><td>回到 F 第一轮场景选择</td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（F3a/F3b/F3c），用户选择后：</p><ul><li>F3c：重新显示 F 第一轮场景选择（§四-F 第一轮）</li><li>F3a/F3b：进入&quot;场景向导终结规则&quot;（§四-F 终结规则），根据推荐命令提示执行</li></ul><h4 id="§f-4-需求变更" tabindex="-1">§F.4 需求变更 <a class="header-anchor" href="#§f-4-需求变更" aria-label="Permalink to &quot;§F.4 需求变更&quot;">​</a></h4><p>直接推荐 → <code>dev:fix --drift &quot;描述&quot;</code>（提示输入变更内容）</p><h4 id="§f-5-中断恢复" tabindex="-1">§F.5 中断恢复 <a class="header-anchor" href="#§f-5-中断恢复" aria-label="Permalink to &quot;§F.5 中断恢复&quot;">​</a></h4><p>直接推荐 → 检查 S1，有活跃流程 → 恢复；无 → 提示&quot;未检测到活跃流程，是否改为 F1 新需求？&quot;</p><h4 id="§f-6-跨项目修复" tabindex="-1">§F.6 跨项目修复 <a class="header-anchor" href="#§f-6-跨项目修复" aria-label="Permalink to &quot;§F.6 跨项目修复&quot;">​</a></h4><p>直接推荐 → <code>dev-flow &lt;描述&gt;</code>（步骤 2 会自动检测跨项目依赖）</p><h4 id="§f-7-流程产物-数据异常" tabindex="-1">§F.7 流程产物/数据异常 <a class="header-anchor" href="#§f-7-流程产物-数据异常" aria-label="Permalink to &quot;§F.7 流程产物/数据异常&quot;">​</a></h4><blockquote><p>流程已完成但仪表盘、度量、文档等产物与预期不一致。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">选项</th><th>引导问题</th><th>推荐命令</th></tr></thead><tbody><tr><td style="text-align:center;">F7a</td><td>仪表盘看不到刚完成的需求（可能只是没刷新）</td><td><code>dev:metrics --dashboard</code></td></tr><tr><td style="text-align:center;">F7b</td><td>怀疑度量 YAML 文件缺失，需要排查</td><td><code>dev:metrics --all</code> → 确认缺失后手动补建 → <code>dev:metrics --dashboard</code></td></tr><tr><td style="text-align:center;">F7c</td><td>文档（devlog/knowledge/文档平台方案）与代码状态不一致</td><td><code>dev:sync</code></td></tr><tr><td style="text-align:center;">F7d</td><td>不确定问题在哪，帮我全面诊断</td><td>先 <code>dev:status</code> → <code>dev:metrics --all</code> 对比一致性</td></tr><tr><td style="text-align:center;">F7e</td><td>← 返回上一级</td><td>回到 F 第一轮场景选择</td></tr></tbody></table><p><strong>交互指令</strong>：</p><p>先输出表格 + <code>ask_followup_question</code>（F7a/F7b/F7c/F7d/F7e），用户选择后：</p><ul><li>F7e：重新显示 F 第一轮场景选择（§四-F 第一轮）</li><li>F7a~F7d：进入&quot;场景向导终结规则&quot;（§四-F 终结规则），根据推荐命令提示执行</li></ul><h3 id="场景向导终结规则" tabindex="-1">场景向导终结规则 <a class="header-anchor" href="#场景向导终结规则" aria-label="Permalink to &quot;场景向导终结规则&quot;">​</a></h3><ul><li>推荐单一命令 → 直接提示执行（&quot;将执行 <code>{命令}</code>，是否需要额外描述？&quot;）</li><li>推荐多命令 → 弹出选项让用户选择</li></ul><h2 id="五、终结点路由表" tabindex="-1">五、终结点路由表 <a class="header-anchor" href="#五、终结点路由表" aria-label="Permalink to &quot;五、终结点路由表&quot;">​</a></h2><blockquote><p>所有 <code>0</code> 结尾的导航选项（A0~F0）：行为均为<strong>重新显示主菜单（一级菜单 §三）</strong>，不执行任何命令，不进入步骤流程。 <code>F1e/F2d/F3c/F7e</code>：行为为<strong>重新显示 F 第一轮场景选择（§四-F）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">选项 ID</th><th>命令</th><th style="text-align:center;">行为类型</th><th style="text-align:center;">是否进步骤流程</th><th>额外提示</th></tr></thead><tbody><tr><td style="text-align:center;">A0</td><td>返回主菜单</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 §三</td></tr><tr><td style="text-align:center;">A1</td><td><code>dev-flow &lt;描述&gt;</code></td><td style="text-align:center;">需输入→入流程</td><td style="text-align:center;">✅</td><td>&quot;请描述你要开发或修复的内容：&quot;</td></tr><tr><td style="text-align:center;">A2</td><td><code>dev-flow --fast &lt;描述&gt;</code></td><td style="text-align:center;">需输入→入流程</td><td style="text-align:center;">✅</td><td>&quot;请描述你要开发或修复的内容：&quot;</td></tr><tr><td style="text-align:center;">A3</td><td><code>--micro &lt;位置&gt; &lt;改动&gt;</code></td><td style="text-align:center;">需输入→入流程</td><td style="text-align:center;">✅</td><td>&quot;请提供文件路径、行号和改动描述：&quot;</td></tr><tr><td style="text-align:center;">B0</td><td>返回主菜单</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 §三</td></tr><tr><td style="text-align:center;">B1</td><td>自然语言恢复</td><td style="text-align:center;">入流程</td><td style="text-align:center;">✅</td><td>&quot;请描述你想继续做什么：&quot;</td></tr><tr><td style="text-align:center;">B2</td><td><code>dev:fix --iteration &quot;描述&quot;</code></td><td style="text-align:center;">需输入→入流程</td><td style="text-align:center;">✅</td><td>&quot;请描述本次反馈/问题：&quot;</td></tr><tr><td style="text-align:center;">B3</td><td><code>dev:fix --drift &quot;描述&quot;</code></td><td style="text-align:center;">需输入→入流程</td><td style="text-align:center;">✅</td><td>&quot;请描述需求变更内容：&quot;</td></tr><tr><td style="text-align:center;">B4</td><td>&quot;继续下一批&quot;</td><td style="text-align:center;">即执行→入流程</td><td style="text-align:center;">✅</td><td>—</td></tr><tr><td style="text-align:center;">B5</td><td>&quot;少问我&quot; 或 &quot;每步都问我&quot;</td><td style="text-align:center;">需选择→执行</td><td style="text-align:center;">❌</td><td>弹出二选一</td></tr><tr><td style="text-align:center;">C0</td><td>返回主菜单</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 §三</td></tr><tr><td style="text-align:center;">C1</td><td><code>dev:sync</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">C2</td><td><code>dev:kb</code></td><td style="text-align:center;">入流程</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">D0</td><td>返回主菜单</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 §三</td></tr><tr><td style="text-align:center;">D1</td><td><code>dev:status</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">D2</td><td><code>dev:status --trace</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">D3</td><td><code>dev:metrics</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">D4</td><td><code>dev:metrics --all</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">D5</td><td><code>dev:metrics --trend</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">D6</td><td><code>dev:metrics --report &lt;ID&gt;</code></td><td style="text-align:center;">需输入</td><td style="text-align:center;">❌</td><td>&quot;请输入需求 ID：&quot;</td></tr><tr><td style="text-align:center;">D7</td><td><code>dev:metrics --dashboard</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">E0</td><td>返回主菜单</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 §三</td></tr><tr><td style="text-align:center;">E1</td><td><code>dev:onboard</code></td><td style="text-align:center;">入流程</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">E2</td><td><code>dev:flowchart</code></td><td style="text-align:center;">入流程</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">E3</td><td><code>dev:help</code></td><td style="text-align:center;">即执行</td><td style="text-align:center;">❌</td><td>—</td></tr><tr><td style="text-align:center;">F0</td><td>返回主菜单</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 §三</td></tr><tr><td style="text-align:center;">F1~F7</td><td>见 §四-F 场景向导</td><td style="text-align:center;">多轮→推荐命令</td><td style="text-align:center;">视推荐而定</td><td>—</td></tr><tr><td style="text-align:center;">F1e/F2d/F3c/F7e</td><td>返回 F 第一轮</td><td style="text-align:center;">导航</td><td style="text-align:center;">❌</td><td>重新显示 F 第一轮场景选择</td></tr></tbody></table><h2 id="六、完成协议" tabindex="-1">六、完成协议 <a class="header-anchor" href="#六、完成协议" aria-label="Permalink to &quot;六、完成协议&quot;">​</a></h2><p>dev:ask <strong>不输出步骤完成标记 JSON</strong>，不进入 dev-flow 步骤体系。</p><ul><li><strong>导航类</strong>（A0/B0/C0/D0/E0/F0/F1e/F2d/F3c/F7e）：重新显示目标菜单（主菜单 §三 或 F 第一轮场景选择），<strong>不执行任何命令</strong>，不进入任何流程</li><li><strong>即执行类</strong>：执行命令后输出简短确认，如 <code>✅ 已执行 dev:status</code> + 命令结果</li><li><strong>需输入→入流程类</strong>：收集输入后进入 dev-flow 流程（加载 flow.md + 步骤链）</li><li><strong>场景向导类</strong>：推荐命令后执行，流程同上</li></ul><p>不需要更新工作上下文，不需要写 .flow 文件。</p>`,99)])])}const u=e(n,[["render",a]]);export{x as __pageData,u as default};
